use std :: fs ; use std :: path :: Path ; use regex :: Regex ; use std :: collections :: HashSet ; fn scan_cargo_toml (dir : & Path , regex : & Regex , refs : & mut HashSet < String >) { let toml_path = dir . join ("Cargo.toml") ; if let Ok (content) = fs :: read_to_string (& toml_path) { for cap in regex . find_iter (& content) { let url = cap . as_str () ; if url . contains ("github.com") || url . contains ("gitlab.com") || url . contains ("bitbucket.org") { refs . insert (url . to_string ()) ; } } } if let Ok (lock_content) = fs :: read_to_string (dir . join ("Cargo.lock")) { for cap in regex . find_iter (& lock_content) { let url = cap . as_str () ; if url . contains ("github.com") || url . contains ("gitlab.com") || url . contains ("bitbucket.org") { refs . insert (url . to_string ()) ; } } } }